import { resolveCanvasColor } from '../../../internal/canvas-color.js';

/**
 * Last-resort series colours, used when the theme tokens cannot be resolved at all -- no DOM, or a
 * `--lr-color-chart-*` that fails to parse.
 *
 * GENERATED by scripts/generate-chart-palette.mjs; do not edit by hand. It was hand-written once
 * and drifted into shipping the pre-8.0.0 ramp long after the CSS ramp was regenerated: half of it
 * fell below WCAG 1.4.11's 3:1 against the page surface (worst 1.54:1), and entries 5-8 were tints
 * of 1-4, so the set collapsed to four colours under red-green colour-vision deficiency. Both are
 * properties `scripts/check-contrast.mjs` asserts -- but only of the CSS ramp, which never saw this
 * array.
 */
/* chart fallback: generated -- see scripts/generate-chart-palette.mjs */
const FALLBACK_SERIES_PALETTE = [
  '#0e006e',
  '#4d011a',
  '#862002',
  '#503983',
  '#315fdd',
  '#935e7c',
  '#de6906',
  '#8f81d3',
] as const;
/* chart fallback: end */

const AREA_FILL_PERCENT = 28;
export { resolveCanvasColor, resolveCanvasColors } from '../../../internal/canvas-color.js';

/**
 * Resolves the categorical chart ramp to concrete canvas-safe colors. Passing `null` selects the
 * deterministic fallback directly; omitting the argument reads the document theme.
 */
export function seriesPalette(element?: Element | null): string[] {
  const target =
    element === undefined && typeof document !== 'undefined'
      ? document.documentElement
      : element;
  if (!target || typeof getComputedStyle !== 'function') {
    return [...FALLBACK_SERIES_PALETTE];
  }

  const cs = getComputedStyle(target);
  return FALLBACK_SERIES_PALETTE.map((fallback, index) => {
    const number = index + 1;
    const color =
      cs.getPropertyValue(`--lr-color-chart-${number}`).trim() ||
      cs.getPropertyValue(`--lr-theme-color-chart-${number}`).trim() ||
      fallback;
    return resolveCanvasColor(target, color, fallback);
  });
}

/**
 * Resolves a translucent area fill through the live theme scope before Chart.js hands it to the
 * canvas. The short-lived probe is necessary because canvas silently ignores unresolved
 * `var()`/unsupported color expressions.
 */
export function translucentAreaColor(scope: Element, color: string): string {
  if (typeof document === 'undefined' || typeof getComputedStyle !== 'function') return color;
  const concrete = resolveCanvasColor(scope, color, color);
  return resolveCanvasColor(
    scope,
    `color-mix(in srgb, ${concrete} ${AREA_FILL_PERCENT}%, transparent)`,
    concrete,
  );
}

/**
 * Defensive JS-side fallbacks for `themeColors()`-style resolvers, mirroring the light-mode default
 * of each `--lr-chart-*` token's own CSS fallback chain -- only reached if `getComputedStyle`
 * somehow can't resolve the custom property at all (e.g. host detached from the document). Shared
 * by `chart.class.ts` and `box-plot.class.ts`, which both default to the same semantic tokens.
 */
export const FALLBACK_GRID_COLOR = '#8a8a90';
export const FALLBACK_TICK_COLOR = '#6b7280';
export const FALLBACK_LEGEND_COLOR = '#1a1a1a';
export const FALLBACK_TOOLTIP_BG = '#fff';
export const FALLBACK_TOOLTIP_TEXT = '#1a1a1a';
/** Mirrors Chart.js's OWN built-in tick font size (`defaults.font.size`, 12px, unrelated to any
 *  `--lr-*` token) -- reached only if `getComputedStyle` can't resolve
 *  `--lr-chart-tick-font-size`/`--_lr-chart-tick-font-size` at all. The canvas charts never set a
 *  font size before `--lr-chart-tick-font-size` existed, so an unset token must keep resolving to
 *  Chart.js's own default rather than a library token -- unlike `<lr-lite-chart>`'s SVG
 *  `[part='axis-label']`, which already hardcoded `--lr-font-size-2xs` and keeps that default. */
export const FALLBACK_TICK_FONT_SIZE = 12;

/** Shared canvas theme-color contract every `chart.class.ts`/`box-plot.class.ts` scale, legend, and
 *  tooltip resolver reads from. */
export interface ChartThemeColors {
  grid: string;
  tick: string;
  legend: string;
  tooltipBg: string;
  tooltipText: string;
  /** Axis tick-label font size in pixels, resolved from `--lr-chart-tick-font-size`. */
  tickFontSize: number;
}
